CREATE DATABASE IF NOT EXISTS cinebook_db;
USE cinebook_db;
CREATE TABLE IF NOT EXISTS movies(movie_id BIGINT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(150) NOT NULL,genre VARCHAR(80) NOT NULL,language VARCHAR(50) NOT NULL,duration_minutes INT NOT NULL,release_date DATE NOT NULL,poster_url VARCHAR(500),description TEXT,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS screens(screen_id BIGINT PRIMARY KEY AUTO_INCREMENT,screen_name VARCHAR(80) NOT NULL,capacity INT NOT NULL);
CREATE TABLE IF NOT EXISTS seats(seat_id BIGINT PRIMARY KEY AUTO_INCREMENT,screen_id BIGINT NOT NULL,seat_number VARCHAR(10) NOT NULL,seat_type VARCHAR(30) NOT NULL DEFAULT 'REGULAR',UNIQUE(screen_id,seat_number),FOREIGN KEY(screen_id) REFERENCES screens(screen_id));
CREATE TABLE IF NOT EXISTS shows(show_id BIGINT PRIMARY KEY AUTO_INCREMENT,movie_id BIGINT NOT NULL,screen_id BIGINT NOT NULL,show_date DATE NOT NULL,show_time TIME NOT NULL,ticket_price DECIMAL(10,2) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(movie_id) REFERENCES movies(movie_id),FOREIGN KEY(screen_id) REFERENCES screens(screen_id),UNIQUE(screen_id,show_date,show_time));
CREATE TABLE IF NOT EXISTS show_seats(show_id BIGINT NOT NULL,seat_id BIGINT NOT NULL,seat_number VARCHAR(10) NOT NULL,seat_type VARCHAR(30) NOT NULL,price DECIMAL(10,2) NOT NULL,status ENUM('AVAILABLE','BOOKED') NOT NULL DEFAULT 'AVAILABLE',PRIMARY KEY(show_id,seat_id),FOREIGN KEY(show_id) REFERENCES shows(show_id),FOREIGN KEY(seat_id) REFERENCES seats(seat_id));
CREATE TABLE IF NOT EXISTS customers(customer_id BIGINT PRIMARY KEY AUTO_INCREMENT,full_name VARCHAR(120) NOT NULL,email VARCHAR(180) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS bookings(booking_id BIGINT PRIMARY KEY AUTO_INCREMENT,customer_id BIGINT NOT NULL,show_id BIGINT NOT NULL,booking_date DATETIME NOT NULL,total_amount DECIMAL(10,2) NOT NULL,booking_status ENUM('CONFIRMED','CANCELLED') NOT NULL DEFAULT 'CONFIRMED',FOREIGN KEY(customer_id) REFERENCES customers(customer_id),FOREIGN KEY(show_id) REFERENCES shows(show_id));
CREATE TABLE IF NOT EXISTS booking_seats(booking_seat_id BIGINT PRIMARY KEY AUTO_INCREMENT,booking_id BIGINT NOT NULL,show_id BIGINT NOT NULL,seat_id BIGINT NOT NULL,ticket_price DECIMAL(10,2) NOT NULL,UNIQUE(show_id,seat_id),FOREIGN KEY(booking_id) REFERENCES bookings(booking_id),FOREIGN KEY(show_id,seat_id) REFERENCES show_seats(show_id,seat_id));
CREATE TABLE IF NOT EXISTS payments(payment_id BIGINT PRIMARY KEY AUTO_INCREMENT,booking_id BIGINT NOT NULL,amount DECIMAL(10,2) NOT NULL,payment_method VARCHAR(30) NOT NULL,payment_status ENUM('SUCCESS','REFUNDED','FAILED') NOT NULL,paid_at DATETIME,FOREIGN KEY(booking_id) REFERENCES bookings(booking_id));
CREATE TABLE IF NOT EXISTS refunds(refund_id BIGINT PRIMARY KEY AUTO_INCREMENT,booking_id BIGINT NOT NULL,refund_amount DECIMAL(10,2) NOT NULL,refund_status ENUM('PENDING','COMPLETED','FAILED') NOT NULL DEFAULT 'COMPLETED',refunded_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(booking_id) REFERENCES bookings(booking_id));

