INSERT IGNORE INTO seats(screen_id,seat_number,seat_type)
SELECT 1,CONCAT(CHAR(65+FLOOR((n-1)/10)),MOD(n-1,10)+1),'REGULAR' FROM (
SELECT 1 n UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10
UNION SELECT 11 UNION SELECT 12 UNION SELECT 13 UNION SELECT 14 UNION SELECT 15 UNION SELECT 16 UNION SELECT 17 UNION SELECT 18 UNION SELECT 19 UNION SELECT 20
UNION SELECT 21 UNION SELECT 22 UNION SELECT 23 UNION SELECT 24 UNION SELECT 25 UNION SELECT 26 UNION SELECT 27 UNION SELECT 28 UNION SELECT 29 UNION SELECT 30
UNION SELECT 31 UNION SELECT 32 UNION SELECT 33 UNION SELECT 34 UNION SELECT 35 UNION SELECT 36 UNION SELECT 37 UNION SELECT 38 UNION SELECT 39 UNION SELECT 40) nums;
INSERT INTO movies(title,genre,language,duration_minutes,release_date,description)
SELECT 'Sample Action Movie','Action','Tamil',145,CURDATE(),'Demo movie for CineBook'
WHERE NOT EXISTS(SELECT 1 FROM movies WHERE title='Sample Action Movie');
INSERT INTO shows(movie_id,screen_id,show_date,show_time,ticket_price)
SELECT m.movie_id,1,CURDATE(),'18:00:00',150 FROM movies m WHERE m.title='Sample Action Movie'
AND NOT EXISTS(SELECT 1 FROM shows s WHERE s.movie_id=m.movie_id AND s.screen_id=1 AND s.show_date=CURDATE() AND s.show_time='18:00:00');
INSERT IGNORE INTO show_seats(show_id,seat_id,seat_number,seat_type,price,status)
SELECT sh.show_id,se.seat_id,se.seat_number,se.seat_type,sh.ticket_price,'AVAILABLE' FROM shows sh JOIN seats se ON se.screen_id=sh.screen_id;
